const webhookData = $('Slash Command Webhook').first().json;
function findField(name) {
  if (webhookData.body && typeof webhookData.body === 'object' && webhookData.body[name] !== undefined) return String(webhookData.body[name]);
  if (webhookData[name] !== undefined && webhookData[name] !== '') return String(webhookData[name]);
  if (webhookData.body && typeof webhookData.body === 'string') { const p = new URLSearchParams(webhookData.body); const v = p.get(name); if (v) return v; }
  return '';
}
const text = (findField('text') || '').trim().toLowerCase();
let subcommand = 'digest', args = '';
if (text.startsWith('calibrate')) { subcommand = 'calibrate'; args = text.replace(/^calibrate\s*/, '').trim(); }
else if (text.startsWith('target')) { subcommand = 'targets'; args = text.replace(/^targets?\s*/, '').trim(); }
else if (text.startsWith('help')) { subcommand = 'help'; }
else if (text) { args = text; }
const acks = { digest: 'Running Account Insights analysis (neglected, surging, expansion)... Results in 2-4 minutes.', calibrate: 'Running ICP Calibration — analyzing closed-won vs closed-lost accounts... Results in 3-5 minutes.', targets: 'Surfacing target accounts matching your ICP profile... Results in 1-2 minutes.', help: '' };
return [{ json: { userId: findField('user_id'), userName: findField('user_name'), channelId: findField('channel_id'), responseUrl: findField('response_url'), commandText: findField('text'), teamDomain: findField('team_domain'), subcommand, args, sales_region: subcommand === 'digest' ? args.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()) : '', ackText: acks[subcommand] || acks.digest } }];
